-- Reviewed vocabulary repairs, 2026-10-26. Ready for a later content publication.
-- This seed changes text only and preserves every image URL and review record.
begin;
create temporary table vocabulary_example_repairs(level text,word text,example text,example_zh text,meaning text) on commit drop;
update public.word_bank w set example=r.example,example_zh=r.example_zh,meaning=coalesce(r.meaning,w.meaning)
from vocabulary_example_repairs r where w.level=r.level and lower(trim(w.word))=r.word;
update public.word_illustrations i set example=r.example,example_zh=r.example_zh,sense=coalesce(r.meaning,i.sense)
from vocabulary_example_repairs r where i.level=r.level and lower(trim(i.word))=r.word;
commit;
